  FacetResult longGetAllChildren(String dim, String... path) {
    validateLongDimAndPath(dim, path);
    if (longInitialized == false) {
      assert longTotCount == 0;
      return new FacetResult(longField, new String[0], longTotCount, new LabelAndValue[0], 0);
    }
    List<LabelAndValue> labelValues = new ArrayList<>();
    for (int i = 0; i < longCounts.length; i++) {
      if (longCounts[i] != 0) {
        labelValues.add(new LabelAndValue(Long.toString(i), longCounts[i]));
      }
    }
    if (longHashCounts.size() != 0) {
      for (LongIntHashMap.LongIntCursor c : longHashCounts) {
        int count = c.value;
        if (count != 0) {
          labelValues.add(new LabelAndValue(Long.toString(c.key), c.value));
        }
      }
    }
    return new FacetResult(
        longField,
        new String[0],
        longTotCount,
        labelValues.toArray(new LabelAndValue[0]),
        labelValues.size());
  }

  FacetResult longGetTopChildren(int topN, String dim, String... path) {
    validateTopN(topN);
    validateLongDimAndPath(dim, path);
    if (longInitialized == false) {
      assert longTotCount == 0;
      return new FacetResult(longField, new String[0], longTotCount, new LabelAndValue[0], 0);
    }
    PriorityQueue<LongCountEntry> pq =
        new PriorityQueue<>(Math.min(topN, longCounts.length + longHashCounts.size())) {
          @Override
          protected boolean lessThan(LongCountEntry a, LongCountEntry b) {
            return a.count < b.count || (a.count == b.count && a.value > b.value);
          }
        };
    int childCount = 0;
    LongCountEntry e = null;
    for (int i = 0; i < longCounts.length; i++) {
      if (longCounts[i] != 0) {
        childCount++;
        if (e == null) {
          e = new LongCountEntry();
        }
        e.value = i;
        e.count = longCounts[i];
        e = pq.insertWithOverflow(e);
      }
    }
    if (longHashCounts.size() != 0) {
      childCount += longHashCounts.size();
      for (LongIntHashMap.LongIntCursor c : longHashCounts) {
        int count = c.value;
        if (count != 0) {
          if (e == null) {
            e = new LongCountEntry();
          }
          e.value = c.key;
          e.count = count;
          e = pq.insertWithOverflow(e);
        }
      }
    }
    LabelAndValue[] results = new LabelAndValue[pq.size()];
    while (pq.size() != 0) {
      LongCountEntry entry = pq.pop();
      results[pq.size()] = new LabelAndValue(Long.toString(entry.value), entry.count);
    }
    return new FacetResult(longField, new String[0], longTotCount, results, childCount);
  }

  FacetResult longGetAllChildrenSortByValue() {
    if (longInitialized == false) {
      assert longTotCount == 0;
      return new FacetResult(longField, new String[0], longTotCount, new LabelAndValue[0], 0);
    }
    List<LabelAndValue> labelValues = new ArrayList<>();
    int[] sortedHashCounts = new int[longHashCounts.size()];
    long[] sortedHashValues = new long[longHashCounts.size()];
    int upto = 0;
    for (LongIntHashMap.LongIntCursor c : longHashCounts) {
      if (c.value != 0) {
        sortedHashCounts[upto] = c.value;
        sortedHashValues[upto] = c.key;
        upto++;
      }
    }
    assert upto == longHashCounts.size()
        : "upto=" + upto + " hashCounts.size=" + longHashCounts.size();
    new InPlaceMergeSorter() {
      @Override
      public int compare(int i, int j) {
        return Long.compare(sortedHashValues[i], sortedHashValues[j]);
      }

      @Override
      public void swap(int i, int j) {
        int x = sortedHashCounts[i];
        sortedHashCounts[i] = sortedHashCounts[j];
        sortedHashCounts[j] = x;
        long y = sortedHashValues[j];
        sortedHashValues[j] = sortedHashValues[i];
        sortedHashValues[i] = y;
      }
    }.sort(0, upto);
    boolean countsAdded = false;
    for (int i = 0; i < upto; i++) {
      if (countsAdded == false && sortedHashValues[i] >= longCounts.length) {
        countsAdded = true;
        appendLongCounts(labelValues);
      }
      labelValues.add(new LabelAndValue(Long.toString(sortedHashValues[i]), sortedHashCounts[i]));
    }
    if (countsAdded == false) {
      appendLongCounts(labelValues);
    }
    return new FacetResult(
        longField,
        new String[0],
        longTotCount,
        labelValues.toArray(new LabelAndValue[0]),
        labelValues.size());
  }

  void appendLongCounts(List<LabelAndValue> labelValues) {
    for (int i = 0; i < longCounts.length; i++) {
      if (longCounts[i] != 0) {
        labelValues.add(new LabelAndValue(Long.toString(i), longCounts[i]));
      }
    }
  }

