  String longCountsToString() {
    StringBuilder b = new StringBuilder();
    b.append("LongValueFacetCounts totCount=");
    b.append(longTotCount);
    if (longInitialized) {
      b.append(":\n");
      for (int i = 0; i < longCounts.length; i++) {
        if (longCounts[i] != 0) {
          b.append("  ");
          b.append(i);
